from fastapi import APIRouter, Depends, HTTPException, Header, status
from sqlalchemy.orm import Session
from typing import Optional
import uuid

from app.database import get_db
from app.schemas.booking import (
    BookingCreate,
    BookingSuccess,
    BookingError,
    BookingResponse,
    ReservationCreate,
    ReservationResponse
)
from app.services.booking_service import BookingService
from app.services.reservation_service import ReservationService
from app.dependencies import (
    get_booking_service,
    get_reservation_service,
    rate_limit_check
)
from app.core.exceptions import (
    BookingException,
    RateLimitExceededError
)
from app.core.logging import get_logger

logger = get_logger(__name__)
router = APIRouter()


@router.post(
    "/reserve",
    response_model=ReservationResponse,
    status_code=status.HTTP_200_OK,
    responses={
        409: {"model": BookingError},
        429: {"description": "Rate limit exceeded"}
    },
    summary="Reserve a seat temporarily",
    description="Reserve a seat for a limited time before final booking"
)
async def reserve_seat(
        reservation: ReservationCreate,
        reservation_service: ReservationService = Depends(get_reservation_service),
        _: None = Depends(rate_limit_check)
):
    """
    Reserve a seat temporarily (10 minutes by default).

    This creates a temporary hold on the seat, preventing others from booking it
    while you complete the checkout process.
    """
    try:
        result = await reservation_service.reserve_seat(
            user_id=reservation.user_id,
            event_id=reservation.event_id,
            seat_id=reservation.seat_id
        )
        return result

    except BookingException as e:
        logger.warning(
            f"Reservation failed: {e.message}",
            extra={
                "user_id": str(reservation.user_id),
                "seat_id": str(reservation.seat_id),
                "error_code": e.error_code
            }
        )
        raise HTTPException(
            status_code=status.HTTP_409_CONFLICT,
            detail={
                "error": e.message,
                "error_code": e.error_code
            }
        )

    except Exception as e:
        logger.error(f"Unexpected error during reservation: {e}", exc_info=True)
        raise HTTPException(
            status_code=status.HTTP_500_INTERNAL_SERVER_ERROR,
            detail="Internal server error"
        )


@router.post(
    "/",
    response_model=BookingSuccess,
    status_code=status.HTTP_201_CREATED,
    responses={
        409: {"model": BookingError},
        429: {"description": "Rate limit exceeded"}
    },
    summary="Book a seat",
    description="Create a final booking for a seat"
)
async def create_booking(
        booking: BookingCreate,
        booking_service: BookingService = Depends(get_booking_service),
        idempotency_key: Optional[str] = Header(None, alias="Idempotency-Key"),
        _: None = Depends(rate_limit_check)
):
    """
    Create a final booking for a seat.

    - **user_id**: UUID of the user making the booking
    - **event_id**: UUID of the event
    - **seat_id**: UUID of the seat to book
    - **Idempotency-Key** (header): Optional key to prevent duplicate bookings

    Returns booking details with confirmation ID.
    """
    try:
        # Use provided idempotency key or generate one
        if not idempotency_key:
            idempotency_key = str(uuid.uuid4())

        result = await booking_service.book_seat(
            user_id=booking.user_id,
            event_id=booking.event_id,
            seat_id=booking.seat_id,
            idempotency_key=idempotency_key
        )

        return result

    except BookingException as e:
        logger.warning(
            f"Booking failed: {e.message}",
            extra={
                "user_id": str(booking.user_id),
                "seat_id": str(booking.seat_id),
                "error_code": e.error_code
            }
        )
        raise HTTPException(
            status_code=status.HTTP_409_CONFLICT,
            detail={
                "success": False,
                "error": e.message,
                "error_code": e.error_code
            }
        )

    except Exception as e:
        logger.error(f"Unexpected error during booking: {e}", exc_info=True)
        raise HTTPException(
            status_code=status.HTTP_500_INTERNAL_SERVER_ERROR,
            detail={
                "success": False,
                "error": "Internal server error",
                "error_code": "INTERNAL_ERROR"
            }
        )


@router.get(
    "/{booking_id}",
    response_model=BookingResponse,
    summary="Get booking details",
    description="Retrieve details of a specific booking"
)
async def get_booking(
        booking_id: uuid.UUID,
        db: Session = Depends(get_db)
):
    """
    Get booking details by booking ID.
    """
    from app.models.booking import Booking

    booking = db.query(Booking).filter(Booking.booking_id == booking_id).first()

    if not booking:
        raise HTTPException(
            status_code=status.HTTP_404_NOT_FOUND,
            detail="Booking not found"
        )

    return booking


@router.get(
    "/user/{user_id}",
    response_model=list[BookingResponse],
    summary="Get user bookings",
    description="Retrieve all bookings for a specific user"
)
async def get_user_bookings(
        user_id: uuid.UUID,
        skip: int = 0,
        limit: int = 100,
        db: Session = Depends(get_db)
):
    """
    Get all bookings for a user with pagination.
    """
    from app.models.booking import Booking

    bookings = db.query(Booking).filter(
        Booking.user_id == user_id
    ).order_by(
        Booking.created_at.desc()
    ).offset(skip).limit(limit).all()

    return bookings


@router.delete(
    "/{booking_id}",
    status_code=status.HTTP_204_NO_CONTENT,
    summary="Cancel booking",
    description="Cancel an existing booking"
)
async def cancel_booking(
        booking_id: uuid.UUID,
        db: Session = Depends(get_db)
):
    """
    Cancel a booking and release the seat.
    """
    from app.models.booking import Booking, BookingStatus
    from app.models.seat import Seat, SeatStatus

    booking = db.query(Booking).filter(Booking.booking_id == booking_id).first()

    if not booking:
        raise HTTPException(
            status_code=status.HTTP_404_NOT_FOUND,
            detail="Booking not found"
        )

    if booking.booking_status == BookingStatus.CANCELLED:
        raise HTTPException(
            status_code=status.HTTP_400_BAD_REQUEST,
            detail="Booking already cancelled"
        )

    try:
        db.begin()

        # Update booking status
        booking.booking_status = BookingStatus.CANCELLED

        # Release seat
        seat = db.query(Seat).filter(Seat.seat_id == booking.seat_id).first()
        if seat:
            seat.status = SeatStatus.AVAILABLE
            seat.booked_by = None
            seat.booked_at = None

        db.commit()

        logger.info(f"Booking cancelled: {booking_id}")

    except Exception as e:
        db.rollback()
        logger.error(f"Failed to cancel booking: {e}", exc_info=True)
        raise HTTPException(
            status_code=status.HTTP_500_INTERNAL_SERVER_ERROR,
            detail="Failed to cancel booking"
        )
